const svg=(paths)=>`<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg>`;
const icons={spark:svg('<path d="m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6L12 2Z"/>'),upload:svg('<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>'),heart:svg('<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>'),link:svg('<path d="m10 13 4-4M8 16l-2 2a4 4 0 0 1-6-6l6-6a4 4 0 0 1 6 0M16 8l2-2a4 4 0 0 1 6 6l-6 6a4 4 0 0 1-6 0" transform="translate(1 0) scale(.9)"/>'),download:svg('<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>'),eye:svg('<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>'),music:svg('<path d="M9 18V5l12-3v13M9 9l12-3"/><ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="18" cy="15" rx="3" ry="2"/>'),photo:svg('<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="2"/><path d="m3 17 5-5 4 4 4-6 5 7"/>')};
const robotChoices=[['happy','Vui vẻ'],['shy','Ngại ngùng'],['love','Thương thương'],['surprised','Bất ngờ'],['sleepy','Mơ màng'],['wink-left','Nháy mắt trái'],['wink-right','Nháy mắt phải · tim bay'],['closed-stars','Nhắm hai mắt · hồi tưởng kỷ niệm']];
const mb=n=>(n/1024/1024).toFixed(1)+' MB';
let dbPromise;
function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('LoiThuongStudio',2);r.onupgradeneeded=()=>{for(const name of ['drafts','projects'])if(!r.result.objectStoreNames.contains(name))r.result.createObjectStore(name,{keyPath:'id'});};r.onsuccess=()=>{r.result.onversionchange=()=>{r.result.close();dbPromise=null;};resolve(r.result);};r.onblocked=()=>{dbPromise=null;reject(Error('Hãy đóng tab Lời Thương đang mở ở phiên bản cũ rồi tải lại trang.'));};r.onerror=()=>{dbPromise=null;reject(Error('Không mở được nơi lưu bản nháp. Hãy tải file sao lưu để giữ nội dung.'));};});return dbPromise;}
async function draftDB(method,value,store='drafts'){const database=await db();return new Promise((resolve,reject)=>{const t=database.transaction(store,['get','getAll'].includes(method)?'readonly':'readwrite'),r=t.objectStore(store)[method](value);let result;r.onsuccess=()=>result=r.result;t.oncomplete=()=>resolve(result);t.onerror=()=>reject(Error('Bộ nhớ bản nháp có thể đã đầy. Hãy tải file sao lưu.'));t.onabort=()=>reject(Error('Chưa lưu được bản nháp.'));});}
export function startEditor(root,{canSave=false,signinPath='/signin-with-chatgpt?return_to=%2F'}={}){
 let config=defaults(),assets=new Map(),urls=new Map(),saved=null,localId=null,lock=false,password='',step=1,robotIndex=0,player=null,view='editor',device='desktop',busy=false,disposed=false,interacted=false,version=0,draftVersion=-1,draftTimer=null,toastTimer=null,modalCleanup=null,publishTask=null,modalVersion=0;
 root.innerHTML=`<div class="studio-app"><header class="st-header"><a href="/" class="st-brand" aria-label="Lời Thương Studio"><span class="st-brand-mark"><i></i><i></i></span><span>Lời Thương<small>STUDIO</small></span></a><nav aria-label="Điều hướng"><button data-action="nav-editor" class="active">Tạo món quà</button><button data-action="nav-library">Quà đã lưu</button><button data-action="help">Hướng dẫn</button></nav><div class="st-header-actions"><span class="st-no-code">Một chút công nghệ. Nhiều chút thương.</span><button class="st-button" data-action="save-local">Lưu vào kho</button><button class="st-button primary" id="headerPublish" data-action="publish">${icons.link} Tạo link & QR</button></div></header><main id="stMain"></main><footer class="st-footer"><span class="st-foot-brand">LỜI THƯƠNG STUDIO</span><span>Những điều nhỏ xinh, được làm bằng cả tấm lòng.</span><button data-action="help">Riêng tư & hướng dẫn ↗</button></footer></div><input id="photosFile" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple hidden><input id="bgFile" type="file" accept="image/jpeg,image/png,image/webp,image/gif" hidden><input id="stickerFile" type="file" accept="image/jpeg,image/png,image/webp,image/gif" hidden><input id="audioFile" type="file" accept="audio/*,.m4a,.mp3" hidden><input id="importFile" type="file" accept=".json,.html" hidden><dialog id="stDialog"><div id="stDialogBody"></div></dialog><div id="stToast" role="status" aria-live="polite"></div>`;
 const $=s=>root.querySelector(s),$$=s=>[...root.querySelectorAll(s)];
 function toast(message,error=false){if(disposed)return;$('#stToast').textContent=message;$('#stToast').className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{if(!disposed)$('#stToast').className='';},4500);}
 function status(message){const el=$('#draftStatus');if(el)el.textContent=message;}
 function cleanUrls(){for(const [id,u]of urls)if(!assets.has(id)){URL.revokeObjectURL(u);urls.delete(id);}}
 function localSource(id){if(!id||!assets.has(id))return '';if(!urls.has(id))urls.set(id,URL.createObjectURL(assets.get(id).blob));return urls.get(id);}
 function updatePreview(){cleanUrls();player?.setConfig(resolveConfig(config,assets,urls));const d=$('#durationLabel');if(d)d.textContent=Math.round(duration(config))+' giây';const s=$('#sceneCount');if(s)s.textContent=config.steps.length+' phân cảnh';const photoCount=$('#photoCount');if(photoCount)photoCount.textContent=config.photos.length+' ảnh';}
 function changed(){interacted=true;version++;status('Đang lưu bản nháp…');updatePreview();clearTimeout(draftTimer);draftTimer=setTimeout(saveDraft,650);}
 async function saveDraft(){const current=version;try{await draftDB('put',{id:'current',config:structuredClone(config),assets:[...assets.entries()].map(([id,a])=>({id,...a})),saved,localId,lock,updated:new Date().toISOString()});draftVersion=current;if(!disposed&&current===version)status('Đã lưu bản nháp trên thiết bị');}catch(e){status('Chưa lưu được bản nháp');toast(e.message,true);}}
 function field(label,key,type='text',hint='',max=120){return `<label class="st-field"><span>${esc(label)}</span><input type="${type}" data-field="${key}" value="${esc(config[key])}" maxlength="${max}">${hint?`<small>${hint}</small>`:''}</label>`;}
 function textField(label,key,rows=2,max=300){return `<label class="st-field"><span>${esc(label)}</span><textarea data-field="${key}" rows="${rows}" maxlength="${max}">${esc(config[key])}</textarea></label>`;}
 function renderEditor(){player?.destroy();view='editor';setNav();$('#stMain').innerHTML=`<div class="st-page-head"><div><div class="st-eyebrow">GỬI MỘT CHÚT DỊU DÀNG</div><h1>Một lời chúc nhỏ.<br><em>Cả một bầu trời thương.</em></h1><p>Viết điều bạn muốn nói. Thêm hình, chọn nhạc.<br>Để những lời thương có một cách xuất hiện thật đặc biệt.</p></div><div class="st-draft-pill"><i></i><span id="draftStatus">${draftVersion===version?'Đã lưu bản nháp trên thiết bị':'Bản nháp của bạn'}</span><button data-action="new" title="Tạo mới">＋</button></div></div><div class="st-editor-layout"><section class="st-form-panel"><div class="st-form-tabs" role="tablist" aria-label="Các bước tạo quà">${[['Lời nhắn','01'],['Hình ảnh','02'],['Robot & nhạc','03'],['Lưu & gửi','04']].map(([label,n],i)=>`<button role="tab" aria-selected="${step===i+1}" data-action="form-step" data-step="${i+1}" class="${step===i+1?'active':''}"><span>${n}</span>${label}</button>`).join('')}</div><div class="st-form-body" id="formPanel"></div><div class="st-form-bottom"><span id="formHint">Từng chi tiết đều là của bạn.</span><button class="st-button" data-action="next-form">${step===4?'Xem món quà':'Tiếp theo'} →</button></div></section><section class="st-preview-panel"><div class="st-preview-toolbar"><div><i></i><strong>Xem trước trực tiếp</strong></div><div class="st-device-switch"><button data-action="device" data-device="desktop" class="${device==='desktop'?'active':''}" aria-label="Xem trên máy tính">▱</button><button data-action="device" data-device="mobile" class="${device==='mobile'?'active':''}" aria-label="Xem trên điện thoại">▯</button></div><button data-action="robot-edit" class="st-button small">Chỉnh robot</button><button data-action="preview" class="st-preview-open">${icons.eye} Mở quà</button></div><div class="st-preview-space ${device==='mobile'?'mobile':''}" id="previewSpace"><div class="st-preview-browser"><div class="st-browser-chrome"><i></i><i></i><i></i><span>Một món quà, chỉ dành cho cậu.</span><b>♡</b></div><div id="giftPreview" class="st-preview-stage"></div></div></div><div class="st-preview-caption"><div class="st-preview-spark">✧</div><div><strong>Lời thương, theo cách của riêng bạn.</strong><p>Chữ, hình ảnh và nhạc đều được lấy từ form bên cạnh.</p></div><span id="durationLabel">${Math.round(duration(config))} giây</span></div><div class="st-scene-strip" id="sceneStrip"></div></section></div>`;renderPanel();player=mountGift($('#giftPreview'),resolveConfig(config,assets,urls),{autoStart:true,muted:true,preview:true,onStep:index=>{if(disposed)return;$$('.st-scene-chip').forEach((b,i)=>b.classList.toggle('active',i===index));}});renderSceneStrip();}
 function setNav(){$$('header nav button[data-action]').forEach(b=>b.classList.toggle('active',b.dataset.action===(view==='editor'?'nav-editor':'nav-library')));$('#headerPublish').innerHTML=icons.link+' '+(saved?'Cập nhật & lấy link':'Tạo link & QR');}
 function renderSceneStrip(){const strip=$('#sceneStrip');if(!strip)return;strip.innerHTML=config.steps.map((s,i)=>`<button class="st-scene-chip ${i===(player?.getState().index||0)?'active':''}" data-action="scene-preview" data-index="${i}"><span>${String(i+1).padStart(2,'0')}</span>${esc(s.line.length>22?s.line.slice(0,22)+'…':s.line)}</button>`).join('');}
 function renderPanel(){const panel=$('#formPanel');if(!panel)return;$$('.st-form-tabs button').forEach((b,i)=>{b.classList.toggle('active',i+1===step);b.setAttribute('aria-selected',String(i+1===step));});$('.st-form-bottom [data-action]').textContent=step===4?'Xem món quà →':'Tiếp theo →';const titles=[['Viết những điều muốn gửi.','Một cái tên, một lời thương, một người thật đặc biệt. Chọn nháy mắt hoặc nhắm hai mắt trong từng đoạn; trái / phải tính theo phía bạn nhìn.'],['Những hình ảnh của riêng bạn.','Ảnh thật, kỷ niệm thật. Giữ trọn những điều thân quen.'],['Chỉnh robot. Thêm nhạc & màu.','Chọn đoạn và biểu cảm mắt ngay bên dưới.'],['Sẵn sàng gửi một điều đẹp đẽ.','Xem lại, lưu và chọn cách đưa món quà đến người nhận.']];let html=`<div class="st-panel-heading"><h2>${titles[step-1][0]}</h2><p>${titles[step-1][1]}</p></div>`;
 if(step===1){html+=field('Tên món quà','projectName','text','Chỉ dùng để bạn quản lý bản nháp và quà đã lưu.',120)+`<div class="st-two">${field('Gửi đến','to','text','',80)}${field('Người gửi','from','text','',100)}</div>`+field('Dịp / dòng chữ nhỏ trên đầu','occasion','text','Ví dụ: 20/10, Sinh nhật, Một ngày bình thường…',100)+`<details class="st-details"><summary>Lời mở đầu & kết thúc</summary>${textField('Lời trên màn mở quà','introTitle',2,200)}${field('Chữ trên nút mở quà','introButton','text','',60)}${textField('Lời nhắn cuối','outro',3,500)}${field('Chữ trên nút xem lại','replayText','text','',60)}</details><div class="st-section-heading"><h3>Các đoạn lời chúc</h3><span id="sceneCount">${config.steps.length} phân cảnh</span></div><p class="st-small-note">Dùng <b>{ten}</b>, <b>{nguoi_gui}</b> hoặc <b>{dip}</b> để tự điền từ thông tin phía trên.</p><button type="button" class="st-button small full" data-action="match-all">Khớp chuyển động cho mọi slide</button><p class="st-small-note">Hai cảnh nối chuyển động, chồng hình và zoom nhẹ. Có thể đổi riêng từng slide bên dưới.</p><div class="st-wishes">${config.steps.map((s,i)=>`<article class="st-wish"><div class="st-wish-top"><span>ĐOẠN ${String(i+1).padStart(2,'0')}</span><div><button type="button" data-action="step-up" data-index="${i}" aria-label="Đưa đoạn ${i+1} lên" ${i===0?'disabled':''}>↑</button><button type="button" data-action="step-down" data-index="${i}" aria-label="Đưa đoạn ${i+1} xuống" ${i===config.steps.length-1?'disabled':''}>↓</button><button type="button" data-action="step-remove" data-index="${i}" aria-label="Xóa đoạn ${i+1}" ${config.steps.length===1?'disabled':''}>×</button></div></div><label class="st-field"><span>Lời chúc chính</span><textarea rows="2" data-step-field="line" data-index="${i}" maxlength="300">${esc(s.line)}</textarea></label><label class="st-field"><span>Dòng nhắn nhỏ</span><textarea rows="2" data-step-field="subline" data-index="${i}" maxlength="300">${esc(s.subline)}</textarea></label><label class="st-field"><span>Hiệu ứng chuyển slide</span><select data-step-field="transition" data-index="${i}">${[['match','Khớp chuyển động · kết hợp'],['match-left','Khớp chuyển động · lướt trái'],['match-right','Khớp chuyển động · lướt phải'],['match-zoom','Khớp chuyển động · zoom'],['fade','Mờ dần nhẹ nhàng'],['slide-left','Trượt sang trái'],['slide-right','Trượt sang phải'],['zoom','Phóng nhẹ'],['none','Không hiệu ứng']].map(([v,t])=>`<option value="${v}" ${(s.transition||'match')===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="st-two"><label class="st-field"><span>Khung cảnh</span><select data-step-field="scene" data-index="${i}">${[['stars','Bầu trời sao'],['flowers','Vườn hoa'],['photo','Ảnh kỷ niệm'],['heart','Trái tim']].map(([v,t])=>`<option value="${v}" ${s.scene===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="st-field"><span>Biểu cảm & nháy mắt robot</span><select data-step-field="emotion" data-index="${i}">${robotChoices.map(([v,t])=>`<option value="${v}" ${s.emotion===v?'selected':''}>${t}</option>`).join('')}</select></label></div><label class="st-field"><span>Hình ảnh trên trang ${i+1}</span><select data-step-field="media" data-index="${i}">${[['auto','Theo khung cảnh hiện tại'],['none','Không hiện hình ảnh'],['decoration','Chỉ ảnh trang trí'],['album','Chỉ album kỷ niệm'],['both','Cả ảnh trang trí và album']].map(([v,t])=>`<option value="${v}" ${(s.media||'auto')===v?'selected':''}>${t}</option>`).join('')}</select><small>Áp dụng riêng cho trang này. Chọn nhắm hai mắt để album bay từ tâm robot sang trái → giữa → phải, mờ dần rồi lặp lại.</small></label><div class="st-two"><label class="st-field"><span>Thời lượng tối thiểu (giây)</span><input type="number" min="3" max="25" step="1" data-step-field="seconds" data-index="${i}" value="${s.seconds}"><small>${sceneTiming(config,s).album?`Tự căn ít nhất ${Math.ceil(sceneTiming(config,s).duration*10)/10} giây: chạy đủ ${config.photos.length} ảnh rồi chờ ít nhất 2 giây.`:'Trang có album sẽ tự kéo dài để chạy đủ ảnh, chờ 2 giây rồi chuyển trang.'}</small></label><label class="st-field"><span>Ảnh bắt đầu album</span><select data-step-field="photoId" data-index="${i}"><option value="">Tự luân phiên</option>${config.photos.map((p,n)=>`<option value="${p.id}" ${s.photoId===p.id?'selected':''}>Ảnh ${n+1}: ${esc(p.caption||assets.get(p.id)?.name||'Kỷ niệm')}</option>`).join('')}</select></label></div></article>`).join('')}</div><button class="st-add-button" data-action="step-add">＋ Thêm một đoạn lời chúc</button>`;}
 if(step===2){html+=`<div class="st-upload" role="button" tabindex="0" data-action="upload-photos"><span>${icons.photo}</span><strong>Thả những kỷ niệm vào đây</strong><p>hoặc nhấn để chọn ảnh từ máy</p><small>JPG, PNG, WebP, GIF · tối đa 12 ảnh</small></div><p class="st-small-note">Album thường đổi ảnh khoảng 1,1 giây/tấm; album hồi tưởng khoảng 3,6 giây/tấm. Trang tự kéo dài để chạy đủ mọi ảnh rồi chờ ít nhất 2 giây trước khi chuyển trang. Khi robot nhắm hai mắt, từng ảnh hiện từ tâm robot, bay trái → giữa → phải rồi mờ dần như ký ức. Chọn ảnh trang trí, album hoặc cả hai cho từng trang ở tab Lời nhắn; ảnh bắt đầu cũng chọn tại đó.</p><div class="st-section-heading"><h3>Album kỷ niệm</h3><span id="photoCount">${config.photos.length} ảnh</span></div><div class="st-photo-list">${config.photos.map((p,i)=>`<article class="st-photo-row"><img src="${esc(localSource(p.id))}" alt="Ảnh kỷ niệm ${i+1}"><div><label class="st-field"><span>Ảnh ${i+1} · chú thích</span><input data-photo-caption="${p.id}" value="${esc(p.caption)}" maxlength="160" placeholder="Một ngày đáng nhớ…"></label><div class="st-photo-row-actions"><button data-action="photo-up" data-index="${i}" ${i===0?'disabled':''}>←</button><button data-action="photo-down" data-index="${i}" ${i===config.photos.length-1?'disabled':''}>→</button><button data-action="photo-remove" data-index="${i}">Xóa ảnh</button></div></div></article>`).join('')||'<div class="st-empty-small">Chưa có ảnh. Món quà vẫn có thể chạy với robot và vườn hoa có sẵn.</div>'}</div><div class="st-upload-secondary"><div><h3>Ảnh nhân vật / hình trang trí</h3><p>PNG nền trong suốt sẽ hòa vào hoạt cảnh đẹp hơn.</p></div>${config.sticker?`<img src="${esc(localSource(config.sticker))}" alt="Hình trang trí"><button class="st-text-button" data-action="remove-sticker">Xóa</button>`:''}<button class="st-button small" data-action="upload-sticker">${config.sticker?'Đổi hình':'Chọn hình'} ↗</button></div><div class="st-upload-secondary"><div><h3>Ảnh nền của bạn</h3><p>Nền phủ kín màn hình bằng lớp mở rộng mềm; ảnh gốc vẫn hiện trọn vẹn.</p></div>${config.background?`<img src="${esc(localSource(config.background))}" alt="Ảnh nền"><button class="st-text-button" data-action="remove-background">Xóa</button>`:''}<button class="st-button small" data-action="upload-background">${config.background?'Đổi nền':'Chọn nền'} ↗</button></div><p class="st-small-note">Không giới hạn MB hoặc kích thước ảnh đầu vào. Ảnh ngang, dọc hay vuông đều tự vừa khung, giữ tỉ lệ và không cắt ảnh. Ảnh lớn được thu gọn để mở nhanh hơn; PNG giữ nền trong suốt; GIF nhỏ giữ chuyển động, GIF lớn tự chuyển thành ảnh tĩnh. Không dùng AI vẽ lại ảnh.</p>`;}
 if(step===3){robotIndex=Math.min(robotIndex,config.steps.length-1);html+=`<section id="robotSettings" class="st-robot-settings"><div class="st-section-heading"><h3>Robot & nháy mắt</h3></div><label class="st-field"><span>Đoạn muốn chỉnh robot</span><select id="robotSceneSelect">${config.steps.map((s,i)=>`<option value="${i}" ${i===robotIndex?'selected':''}>Đoạn ${i+1}: ${esc(s.line.slice(0,38))}</option>`).join('')}</select></label><label class="st-field"><span>Chọn biểu cảm / nháy mắt</span><select id="robotEmotion" data-step-field="emotion" data-index="${robotIndex}">${robotChoices.map(([v,t])=>`<option value="${v}" ${config.steps[robotIndex].emotion===v?'selected':''}>${t}</option>`).join('')}</select></label><p class="st-small-note">Nháy mắt phải có tim bay. Nhắm hai mắt mở nền đen, sao và album hồi tưởng (nếu trang có bật album). Chọn để xem trước ngay; trái / phải tính theo phía bạn nhìn.</p></section><div class="st-music-card"><div class="st-music-disc"><i></i></div><div><h3>${config.audio?esc(assets.get(config.audio)?.name||'Nhạc đã chọn'):'Chọn một bản nhạc.'}</h3><p>${config.audio?mb(assets.get(config.audio)?.blob.size||0):'Một giai điệu khiến lời chúc dịu dàng hơn.'}</p><div class="st-row"><button class="st-button small" data-action="upload-audio">${icons.music} ${config.audio?'Đổi nhạc':'Tải nhạc lên'}</button>${config.audio?'<button class="st-text-button" data-action="remove-audio">Xóa nhạc</button>':''}</div></div></div><label class="st-field st-range"><span>Âm lượng nhạc <b id="volumeValue">${Math.round(config.volume*100)}%</b></span><input data-field="volume" type="range" min="0" max="1" step=".05" value="${config.volume}"></label><p class="st-small-note">MP3, M4A, WAV, OGG, AAC, WebM · tối đa 12 MB. Người nhận chạm “Mở lời thương” để bắt đầu nhạc. Bản xem trước ban đầu tắt tiếng.</p><div class="st-section-heading"><h3>Một bảng màu cho cảm xúc</h3></div><div class="st-themes">${Object.entries(themes).map(([id,t])=>`<button data-action="theme" data-theme="${id}" class="${config.theme===id?'selected':''}"><span style="background:${t.bg}"><i style="background:${t.eyes};box-shadow:0 0 10px ${t.eyes}"></i><i style="background:${t.eyes};box-shadow:0 0 10px ${t.eyes}"></i></span>${t.name}</button>`).join('')}</div><div class="st-two"><label class="st-field st-color"><span>Màu đôi mắt</span><div><input data-field="eyeColor" type="color" value="${esc(config.eyeColor)}"><b>${esc(config.eyeColor)}</b></div></label><label class="st-field st-color"><span>Màu điểm nhấn</span><div><input data-field="accent" type="color" value="${esc(config.accent)}"><b>${esc(config.accent)}</b></div></label></div><div class="st-two"><label class="st-field"><span>Kiểu chữ lời chúc</span><select data-field="font"><option value="sans" ${config.font!=='serif'?'selected':''}>Chữ rõ nét · tiếng Việt</option><option value="serif" ${config.font==='serif'?'selected':''}>Chữ thanh lịch · tiếng Việt</option></select></label><label class="st-field"><span>Tốc độ hoạt cảnh</span><select data-field="speed">${[[.75,'Chậm rãi'],[1,'Vừa đủ'],[1.25,'Nhanh hơn'],[1.5,'Thật nhanh']].map(([v,t])=>`<option value="${v}" ${config.speed===v?'selected':''}>${t}</option>`).join('')}</select></label></div><label class="st-check"><input data-field="particles" type="checkbox" ${config.particles?'checked':''}><span>Sao và trái tim bay nhẹ</span></label><p class="st-small-note">Hoạt cảnh và nhạc tự lặp liên tục. Nút tạm dừng / tiếp tục ở vị trí nút nhạc cũ.</p><label class="st-check"><input data-field="showSignature" type="checkbox" ${config.showSignature?'checked':''}><span>Hiện chữ ký người gửi</span></label>`;}
 if(step===4){html+=`<div class="st-gift-summary"><span>♡</span><h3>${esc(config.projectName)}</h3><p>Gửi ${esc(config.to)} · từ ${esc(config.from||'bạn')}</p><div><b>${config.steps.length} đoạn</b><b>${config.photos.length} ảnh</b><b>${Math.round(duration(config))} giây</b></div></div><label class="st-check st-lock"><input id="lockGift" type="checkbox" ${lock?'checked':''}><span>Đặt mật khẩu mở món quà<small>Mật khẩu mã hóa nội dung và tệp của link / file xuất.</small></span></label><div id="passwordFields" ${lock?'':'hidden'}><label class="st-field"><span>Mật khẩu bạn muốn dùng</span><input id="giftPassword" type="password" autocomplete="new-password" minlength="8" value="${esc(password)}" placeholder="Ít nhất 8 ký tự"></label><p class="st-small-note">Hãy ghi nhớ mật khẩu và gửi riêng cho người nhận. Không có chức năng lấy lại mật khẩu. Bản nháp trên thiết bị không được mã hóa.</p></div><button class="st-button primary full" data-action="publish">${icons.link} ${saved?'Cập nhật link hiện tại':'Tạo link & mã QR'}</button>${saved?`<div class="st-saved-link"><span>LINK HIỆN TẠI</span><a href="${esc(saved.url)}" target="_blank" rel="noopener">${esc(saved.url)}</a><button data-action="share-saved">Sao chép / QR ↗</button></div><button class="st-text-button" data-action="publish-copy">Lưu thành món quà mới</button>`:''}<div class="st-or"><span>lưu trên thiết bị của bạn</span></div><button class="st-button full" data-action="save-local">Lưu vào Quà đã lưu</button><div class="st-row"><button class="st-text-button" data-action="export-json">Sao lưu dự án JSON</button><button class="st-text-button" data-action="import">Nhập lại dự án JSON</button></div><div class="st-info">Kho quà lưu chữ, ảnh và nhạc trên trình duyệt này, không cần đăng nhập. Tải JSON để sao lưu hoặc chuyển máy. Link & QR vẫn được lưu trên website khi bạn đăng nhập.</div>`;}
 panel.innerHTML=html;}
 function showModal(title,sub,body,wide=false){closeModal();$('#stDialogBody').innerHTML=`<div class="st-modal-head"><div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div><button class="st-modal-close" data-action="close-modal" aria-label="Đóng">×</button></div><div class="st-modal-body">${body}</div>`;$('#stDialog').classList.toggle('wide',wide);$('#stDialog').showModal();}
 function closeModal(){modalVersion++;modalCleanup?.();modalCleanup=null;if($('#stDialog').open)$('#stDialog').close();}
 function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000);}
 function ensureConfig(){const valid=validateConfig(config);if(lock&&password.length<8){step=4;if(view!=='editor')renderEditor();else renderPanel();$('#giftPassword')?.focus();throw Error('Nhập mật khẩu ít nhất 8 ký tự trước khi tạo link hoặc tải file.');}return valid;}
 async function publish(copy=false){
  if(busy)throw Error('Đang xử lý nội dung. Đợi một chút nhé.');const valid=ensureConfig();
  if(!canSave){showModal('Lưu lời thương của bạn.','Đăng nhập để lưu nội dung và tạo link/QR.',`<div class="st-info">Bạn có thể lưu vào kho trên thiết bị hoặc tải JSON chứa đủ lời chúc, ảnh và nhạc.</div><a class="st-button primary full" href="${esc(signinPath)}" target="_top">Đăng nhập để tạo link</a><button class="st-button full" data-action="export-json">Sao lưu dự án JSON</button>`);return;}
  busy=true;const task={controller:new AbortController(),committing:false};publishTask=task;
  showModal('Đang gói ghém lời thương…','Ảnh và nhạc đang được lưu cùng món quà.',`<div class="st-loading-heart">♡</div><p id="publishProgress" class="st-progress-text">Đang chuẩn bị nội dung…</p>`);
  const close=$('#stDialog [data-action="close-modal"]');close.setAttribute('aria-label','Hủy tạo link');close.title='Hủy tạo link';
  try{
   const result=await saveOnline(valid,assets,lock?password:'',copy?null:saved,t=>{if(disposed||task.controller.signal.aborted)return;const p=$('#publishProgress');if(p)p.textContent=t;},{signal:task.controller.signal,onCommit:()=>{task.committing=true;if(!disposed){close.disabled=true;close.setAttribute('aria-label','Đang hoàn tất lưu');close.title='Đang hoàn tất lưu, vui lòng đợi một chút.';}}});
   saved={...result,title:valid.projectName,encrypted:lock};await saveDraft();
   if(disposed)return;
   try{await saveLocal(true);}catch(e){toast('Link đã tạo. Chưa lưu được vào kho thiết bị: '+e.message,true);}
   if(disposed)return;
   setNav();busy=false;publishTask=null;await shareModal(saved);toast('Đã lưu món quà. Link này có thể mở lại sau khi tải lại trang.');
  }catch(e){
   if(task.controller.signal.aborted||disposed)return;
   showModal('Chưa tạo được link.',e.message,'<div class="st-row"><button class="st-button primary" data-action="publish">Thử lại</button><button class="st-button" data-action="export-json">Sao lưu dự án JSON</button></div>');throw e;
  }finally{if(publishTask===task)publishTask=null;busy=false;}
 }
 function dismissModal(){
  if(publishTask){
   if(publishTask.committing){toast('Đang hoàn tất lưu, vui lòng đợi một chút.');return;}
   publishTask.controller.abort();closeModal();toast('Đã hủy tạo link. Lời nhắn, ảnh và nhạc của bạn vẫn được giữ nguyên.');return;
  }
  if(!busy)closeModal();
 }
 let qrPromise=null;
 function loadQR(){if(window.qrcode)return Promise.resolve(window.qrcode);if(!qrPromise)qrPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='/qr.js';s.onload=()=>resolve(window.qrcode);s.onerror=()=>{qrPromise=null;reject(Error('Chưa tải được QR. Bạn vẫn có thể sao chép link.'));};document.head.append(s);});return qrPromise;}
 async function shareModal(item){const revision=modalVersion;const link=recipientURL(item,location.origin);const response=await fetch('/api/gifts/'+item.id);if(disposed||revision!==modalVersion)return;if(!response.ok)throw Error('Món quà chưa có trên website này. Chọn Lưu thành món quà mới để tạo link và QR tại đây.');const remote=await response.json();if(disposed||revision!==modalVersion)return;showModal('Lời thương đã có địa chỉ.','Sao chép link hoặc tải mã QR trái tim cho người nhận.',`<div class="st-share-card"><div class="st-qr" id="qrBox"><span>Đang tạo QR…</span></div><div><div class="st-eyebrow">MÓN QUÀ CỦA BẠN</div><h3>${esc(item.title||config.projectName)}</h3><p>${(item.encrypted??remote.envelope?.encrypted??false)?'Đã mã hóa bằng mật khẩu. Gửi mật khẩu riêng cho người nhận.':'Ai có link và quyền truy cập website đều có thể mở món quà.'}</p><label class="st-field"><span>Link mở món quà</span><input readonly id="shareUrl" value="${esc(link)}"></label><div class="st-row"><button class="st-button primary" data-action="copy-link">Sao chép link</button><a class="st-button" href="${esc(link)}" target="_blank" rel="noopener">Mở thử ↗</a></div></div></div><div class="st-row" style="margin-top:20px"><button class="st-button" data-action="download-qr" disabled>Đang tạo ảnh QR…</button></div><p class="st-small-note">Quét QR để mở trang món quà → bấm Mở lời thương để xem trực tiếp, không cần tải file. Nếu đã đặt mật khẩu, người nhận cần nhập mật khẩu trước.</p>`,true);const box=$('#qrBox');try{const qr=await loadQR();if(box?.isConnected&&$('#qrBox')===box){box.innerHTML=heartQR(qr,link);const png=await qrPNG(box.querySelector('svg'));if(disposed||!box.isConnected||$('#qrBox')!==box)return;const url=URL.createObjectURL(png),button=$('[data-action="download-qr"]'),a=document.createElement('a');a.className='st-button';a.dataset.action='download-qr';a.href=url;a.download=safeName(item.title||config.projectName)+'-QR.png';a.textContent='Tải QR trái tim (PNG)';button.replaceWith(a);modalCleanup=()=>URL.revokeObjectURL(url);}}catch(e){toast(e.message,true);}}
 async function exportFile(){if(busy)throw Error('Đang xử lý tệp. Đợi một chút nhé.');const valid=ensureConfig();busy=true;toast('Đang đóng gói chữ, ảnh và nhạc…');try{const packet=await portablePacket(valid,assets,lock?password:'');download(new Blob([JSON.stringify(packet)],{type:'application/json;charset=utf-8'}),safeName(valid.projectName)+'.loithuong.json');toast('Đã tải file sao lưu JSON về máy.');}finally{busy=false;}}
 function preview(){const valid=validateConfig(config);player?.goTo(player.getState().index);showModal('Món quà khi người nhận mở.','Nhấn nút mở để bắt đầu hoạt cảnh và nhạc.',`<div class="st-recipient-preview" id="recipientPreview"></div>`,true);const p=mountGift($('#recipientPreview'),resolveConfig(valid,assets,urls),{autoStart:false,muted:false});modalCleanup=()=>p.destroy();}
 async function addFiles(files,kind){if(busy)throw Error('Đang xử lý. Bạn đợi một chút nhé.');if(!files.length)return;busy=true;let added=0,notes=new Set();toast(kind==='audio'?'Đang thêm nhạc…':'Đang tự tối ưu ảnh…');try{for(const f of files){if(kind==='photo'&&config.photos.length>=LIMITS.photos){toast('Mỗi món quà hỗ trợ tối đa 12 ảnh.',true);break;}const asset=kind==='audio'?await prepareAudio(f):await prepareImage(f,kind);if(asset.note)notes.add(asset.note);const old=kind==='photo'?null:config[kind];let current=sizeOf(assets)-(old?assets.get(old)?.blob.size||0:0);if(kind!=='audio'&&current+asset.blob.size>LIMITS.total){const optimized=new Map();for(const [ref,previous]of assets){if(ref===old||!previous.mime.startsWith('image/'))continue;const next=await prepareImage(new File([previous.blob],previous.name,{type:previous.mime}),previous.kind);optimized.set(ref,next);if(next.note)notes.add(next.note);}for(const [ref,next]of optimized){assets.set(ref,next);if(urls.has(ref)){URL.revokeObjectURL(urls.get(ref));urls.delete(ref);}}current=sizeOf(assets)-(old?assets.get(old)?.blob.size||0:0);}if(current+asset.blob.size>LIMITS.total)throw Error('Tổng ảnh và nhạc cần nhỏ hơn 28 MB. Hãy xóa bớt tệp trước khi thêm.');const id=crypto.randomUUID();assets.set(id,asset);if(kind==='photo')config.photos.push({id,caption:''});else{if(old)assets.delete(old);config[kind]=id;if(kind==='audio'&&config.audioTitle==='Bản nhạc dành cho cậu')config.audioTitle=f.name.replace(/\.[^.]+$/,'').slice(0,120);}added++;if(kind!=='photo')break;}if(added)toast(`Đã thêm ${added} ${kind==='audio'?'bản nhạc':'hình ảnh'}. ${[...notes].join(' ')}`.trim());}catch(e){if(added)e.message=`Đã thêm ${added} tệp hợp lệ. ${e.message}`;throw e;}finally{if(added){changed();renderPanel();renderSceneStrip();}busy=false;}}
 function removeAsset(field){const id=config[field];config[field]=null;if(id&&!assetRefs(config).includes(id))assets.delete(id);changed();renderPanel();}
 async function readImport(file){if(!file)return;if(file.size>42*1024*1024)throw Error('File dự án vượt 42 MB.');const packet=packetFromText(await file.text());if(packet?.envelope?.encrypted){passwordModal('Mở dự án có mật khẩu',async pass=>{const result=await openPortable(packet,pass);replaceDraft(result.config,result.assets,{lock:true,password:pass});});}else{const result=await openPortable(packet);replaceDraft(result.config,result.assets,{lock:false,password:''});}}
 function replaceDraft(next,nextAssets,options={}){if(interacted&&!confirm('Thay nội dung đang sửa bằng dự án này? Bạn có thể tải file sao lưu trước khi thay.'))return;player?.destroy();for(const u of urls.values())URL.revokeObjectURL(u);urls=new Map();config=next;assets=nextAssets;saved=options.saved||null;localId=options.localId||null;lock=!!options.lock;password=options.password||'';step=1;closeModal();renderEditor();changed();toast('Đã mở nội dung trong form. Bạn có thể chỉnh sửa mọi chi tiết.');}
 function passwordModal(title,fn){showModal(title,'Mật khẩu chỉ được dùng để mở nội dung trong trình duyệt.',`<form id="unlockEditorForm"><label class="st-field"><span>Mật khẩu</span><input id="unlockEditorPassword" type="password" autocomplete="current-password" required></label><p id="unlockEditorError" class="st-form-error" role="status"></p><button class="st-button primary full" type="submit">Mở nội dung</button></form>`);const form=$('#unlockEditorForm');form.addEventListener('submit',async e=>{e.preventDefault();const b=form.querySelector('button');b.disabled=true;$('#unlockEditorError').textContent='Đang mở…';try{await fn($('#unlockEditorPassword').value);}catch(error){if($('#unlockEditorError'))$('#unlockEditorError').textContent=error.message;}finally{b.disabled=false;}});}
 async function saveLocal(quiet=false){const valid=ensureConfig(),id=localId||crypto.randomUUID(),current=version;const packet=await portablePacket(valid,assets,lock?password:'');await draftDB('put',{id,title:valid.projectName,packet,saved:structuredClone(saved),updated:new Date().toISOString()},'projects');localId=id;await saveDraft();if(!quiet)toast(current===version?'Đã lưu món quà vào kho trên thiết bị.':'Đã lưu bản vừa chụp. Bấm Lưu lại để giữ chỉnh sửa mới nhất.');}
 async function openSaved(id){const item=await draftDB('get',id,'projects');if(!item)throw Error('Món quà không còn trong kho trên thiết bị.');const open=async pass=>{const decoded=await openPortable(item.packet,pass);replaceDraft(decoded.config,decoded.assets,{localId:id,saved:item.saved,lock:item.packet.envelope.encrypted,password:pass});};if(item.packet.envelope.encrypted)passwordModal('Mở món quà đã khóa trong kho',open);else await open('');}
 async function openLegacy(id){const result=await loadOnline(id);const apply=(r,pass='')=>replaceDraft(r.config,r.assets,{saved:{id,revision:r.record.revision,url:location.origin+'/g/'+id,title:r.config.projectName,encrypted:r.record.envelope.encrypted},lock:r.record.envelope.encrypted,password:pass});if(result.locked)passwordModal('Mở lại món quà đã khóa',async pass=>apply(await loadOnline(id,pass),pass));else apply(result);}
 function cardArt(item,index){const value=item.packet?.envelope?.encrypted?null:item.packet?.envelope?.data,c=value?.config,ref=c?.photos?.[0]?.id||c?.sticker||c?.background,a=value?.assets?.find(x=>x.ref===ref);if(a&&['image/jpeg','image/png','image/webp','image/gif'].includes(a.mime)&&typeof a.data==='string'&&/^[A-Za-z0-9+/]*={0,2}$/.test(a.data))return `<div class="st-gift-cover"><img src="data:${a.mime};base64,${a.data}" alt="Ảnh bìa món quà"></div>`;return `<div class="st-gift-card-art" style="--card-hue:${[330,270,190,20][index%4]}"><div class="st-card-eyes"><i></i><i></i></div><span>✧</span><b>♡</b>${item.packet?.envelope?.encrypted?'<small class="st-cover-lock">Có mật khẩu</small>':''}</div>`;}
 async function backupOnline(id){toast('Đang lấy đủ chữ, ảnh và nhạc để sao lưu…');const result=await loadOnline(id);async function save(r,pass=''){const packet=await portablePacket(r.config,r.assets,pass);download(new Blob([JSON.stringify(packet)],{type:'application/json;charset=utf-8'}),safeName(r.config.projectName)+'.loithuong.json');toast('Đã tải bản sao JSON. Link gốc vẫn được giữ nguyên.');}if(result.locked)passwordModal('Sao lưu món quà đã khóa',async pass=>{await save(await loadOnline(id,pass),pass);closeModal();});else await save(result);}

 async function deleteCloudLink(id,button){
  if(!confirm('Xóa link này và các ảnh/nhạc gắn với link trên máy chủ? Link và mã QR này sẽ ngừng hoạt động. Bản lưu trên thiết bị và các link khác vẫn được giữ.'))return;
  busy=true;button.disabled=true;
  try{
   await deleteOnline(id);let localWarning='';
   if(saved?.id===id)saved=null;
   try{
    const copies=await draftDB('getAll',undefined,'projects');
    await Promise.all(copies.filter(item=>item.saved?.id===id).map(item=>draftDB('put',{...item,saved:null},'projects')));
    const draft=await draftDB('get','current');if(draft?.saved?.id===id)await draftDB('put',{...draft,saved:null});
   }catch{localWarning=' Bản trên thiết bị vẫn được giữ, nhưng có thể còn hiển thị link cũ.';}
   await renderLibrary();toast('Đã xóa link. Các bản sao trên thiết bị được giữ nguyên.'+localWarning,!!localWarning);
  }finally{busy=false;if(button.isConnected)button.disabled=false;}
 }
 function oldLinkForm(){
  const box=document.createElement('section');box.className='st-online-library st-old-link-import';
  box.innerHTML='<h2>Đưa link cũ vào kho</h2><p class="st-small-note">Dán link Lời Thương của website này để lưu một bản đầy đủ chữ, ảnh và nhạc vào thiết bị. Link gốc vẫn giữ nguyên. Quà đã khóa cần nhập mật khẩu.</p><form id="oldGiftImportForm"><label class="st-field"><span>Link món quà cũ</span><input id="oldGiftLink" type="url" required placeholder="https://…/g/…" autocomplete="url"></label><button class="st-button" type="submit">Lưu bản sao link cũ vào kho</button></form>';
  $('#giftLibrary')?.append(box);
  box.querySelector('form').addEventListener('submit',e=>{e.preventDefault();void run(()=>importOldLink(box.querySelector('input').value,box.querySelector('button')));});
 }
 async function importOldLink(value,button){
  if(busy)throw Error('Đang xử lý nội dung. Đợi một chút nhé.');
  let link;try{link=new URL(value.trim());}catch{throw Error('Dán đầy đủ link món quà, bắt đầu bằng https:// và có /g/…');}
  const match=link.pathname.match(/^\/g\/([a-f0-9-]{36})\/?$/i);
  if(!match||link.origin!==location.origin||link.username||link.password)throw Error('Dán link /g/… của chính website Lời Thương này. Với link từ website khác, hãy xuất JSON ở website đó rồi nhập lại tại đây.');
  const id=match[1],canonical=new URL('/g/'+id,location.origin).href;
  async function keep(result,pass=''){
   const packet=await portablePacket(result.config,result.assets,pass);
   const copy={id:crypto.randomUUID(),title:result.config.projectName,packet,saved:{id,revision:result.record.revision,url:canonical,title:result.config.projectName,encrypted:!!pass},updated:new Date().toISOString()};
   await draftDB('put',copy,'projects');closeModal();await renderLibrary();toast('Đã thêm bản sao đủ chữ, ảnh và nhạc vào kho. Link gốc và các dự án khác vẫn được giữ.');
  }
  busy=true;button.disabled=true;toast('Đang lấy chữ, ảnh và nhạc từ link cũ…');
  try{
   const result=await loadOnline(id);
   if(result.locked){passwordModal('Đưa món quà đã khóa vào kho',async pass=>{if(busy)throw Error('Đang mở nội dung. Đợi một chút nhé.');busy=true;try{await keep(await loadOnline(id,pass),pass);}finally{busy=false;}});}
   else await keep(result);
  }finally{busy=false;if(button.isConnected)button.disabled=false;}
 }

 async function previousGifts(){if(!canSave)return;const box=document.createElement('section');box.id='onlineGiftLibrary';box.className='st-online-library';box.innerHTML='<h2>Quà đã tạo link trên tài khoản</h2><p class="st-small-note">Link cũ được giữ nguyên. Mở sửa hoặc tải JSON để giữ thêm một bản trên thiết bị.</p><div class="st-online-cards">Đang mở danh sách quà…</div>';$('#giftLibrary')?.append(box);try{const gifts=[];let total=Infinity;while(gifts.length<total){const page=await listOnline(gifts.length);if(view!=='library'||disposed||!box.isConnected)return;if(!page.gifts.length)break;gifts.push(...page.gifts);total=page.total;}if(view!=='library'||disposed||!box.isConnected)return;box.querySelector('.st-online-cards').innerHTML=`<div class="st-library-grid">${gifts.map(g=>`<article class="st-gift-card"><div class="st-gift-card-body"><small>ĐÃ TẠO LINK · ${esc(new Date(g.updated_at).toLocaleDateString('vi-VN'))}</small><h2>${esc(g.title)}</h2><div class="st-row"><button class="st-button small" data-action="edit-legacy" data-id="${esc(g.id)}">Mở / sửa</button><a class="st-button small" href="/g/${esc(g.id)}" target="_blank" rel="noopener">Xem link ↗</a><button class="st-button small" data-action="share-online" data-id="${esc(g.id)}">Link & QR</button><button class="st-text-button" data-action="backup-online" data-id="${esc(g.id)}">Tải JSON</button><button class="st-text-button danger" data-action="delete-online" data-id="${esc(g.id)}">Xóa link</button></div></div></article>`).join('')||'<p class="st-small-note">Chưa có quà đã tạo link trên tài khoản này.</p>'}</div>`;}catch(e){if(box.isConnected)box.querySelector('.st-online-cards').innerHTML=`<p class="st-small-note">${esc(e.message)} Kho trên thiết bị và các link cũ vẫn được giữ.</p><button class="st-button small" data-action="library-refresh">Thử lại</button>`;}}

 async function renderLibrary(){player?.destroy();player=null;view='library';setNav();$('#stMain').innerHTML=`<div class="st-page-head"><div><div class="st-eyebrow">KHO QUÀ CỦA BẠN</div><h1>Mỗi món quà,<br><em>một người đặc biệt.</em></h1><p>Lưu, mở sửa và xóa quà trên thiết bị này. Tải JSON để sao lưu hoặc chuyển máy.</p></div><div class="st-row"><button class="st-button" data-action="import">Nhập JSON</button><button class="st-button primary" data-action="new">＋ Tạo món quà mới</button></div></div><div id="giftLibrary"><div class="st-empty">Đang mở hộp kỷ niệm…</div></div>`;try{const items=(await draftDB('getAll',undefined,'projects')).sort((a,b)=>b.updated.localeCompare(a.updated));if(view!=='library'||disposed)return;$('#giftLibrary').innerHTML=`<div class="st-library-top"><span>${items.length} món quà đã lưu trên thiết bị</span><button class="st-text-button" data-action="library-refresh">Làm mới ↻</button></div><div class="st-library-grid">${items.map((g,i)=>`<article class="st-gift-card">${cardArt(g,i)}<div class="st-gift-card-body"><h2>${esc(g.title)}</h2><p>${g.packet.envelope.encrypted?'Có mật khẩu · ':''}Cập nhật ${new Date(g.updated).toLocaleString('vi-VN')}</p><div class="st-row">${g.saved?.url?`<a class="st-button small" href="${esc(g.saved.url)}" target="_blank" rel="noopener">Mở link ↗</a>`:''}<button class="st-button small" data-action="edit-saved" data-id="${g.id}">Mở / sửa</button><button class="st-text-button" data-action="backup-saved" data-id="${g.id}">Tải JSON</button><button class="st-text-button danger" data-action="delete-saved" data-id="${g.id}">Xóa</button></div></div></article>`).join('')||'<div class="st-empty"><h2>Hộp quà vẫn đang chờ bạn.</h2><p>Bấm “Lưu vào kho” khi tạo quà để giữ đủ chữ, ảnh và nhạc.</p><button class="st-button primary" data-action="nav-editor">Tạo món quà</button></div>'}</div><p class="st-small-note">Kho không đồng bộ giữa thiết bị. Xóa dữ liệu trình duyệt sẽ xóa kho; hãy tải JSON để giữ bản sao. Xóa quà khỏi kho không xóa link đã tạo trên website.</p>`;await previousGifts();if(view==='library'&&!disposed)oldLinkForm();}catch(e){if(view==='library')$('#giftLibrary').innerHTML=`<div class="st-empty"><p>${esc(e.message)}</p><button class="st-button" data-action="library-refresh">Thử lại</button></div>`;}}
 function help(){showModal('Một món quà, bắt đầu từ form.','Bạn không cần chỉnh mã nguồn hoặc dùng dịch vụ AI trả phí.',`<div class="st-help"><h3>1. Viết lời thương</h3><p>Nhập tên người nhận, người gửi và dịp. Sửa, thêm, xóa hoặc đổi thứ tự các đoạn; chọn khung cảnh, biểu cảm, thời lượng. Bấm từng đoạn dưới preview để xem ngay.</p><h3>2. Chọn ảnh và nhạc</h3><p>Album tối đa 12 ảnh; có thể chọn riêng ảnh nền và hình nhân vật PNG nền trong suốt. Ảnh đầu vào không bị giới hạn MB hoặc kích thước: website tự thu gọn bản dùng trên web, giữ tỉ lệ và nền trong suốt. GIF lớn chuyển thành ảnh tĩnh; GIF nhỏ giữ chuyển động. Nhạc tối đa 12 MB. Ảnh được xử lý trên thiết bị, không vẽ lại bằng AI.</p><h3>3. Lưu và gửi</h3><p>Bản nháp tự lưu trên trình duyệt hiện tại, không đồng bộ thiết bị. Bấm Lưu vào kho để giữ chữ, ảnh và nhạc trên thiết bị, không cần đăng nhập. Trong Quà đã lưu, bạn mở sửa, tải JSON hoặc xóa. Tạo link cần đăng nhập; cập nhật món quà đã có link sẽ giữ nguyên địa chỉ.</p><p>Link tuân theo quyền truy cập của website. Bấm Sao lưu dự án JSON để tải đầy đủ nội dung về máy, nhập lại JSON để sửa tiếp.</p><h3>4. Riêng tư và mật khẩu</h3><p>Ai có link và quyền truy cập website có thể xem quà chưa khóa. Bật mật khẩu để mã hóa nội dung và tệp của link/file bằng AES-GCM; mật khẩu không gửi lên máy chủ. Không có khôi phục mật khẩu. Tên quản lý món quà vẫn được lưu để bạn nhận diện trong danh sách của mình.</p><p>Bản nháp trên thiết bị không được mã hóa. Tránh lưu nội dung riêng tư trên máy dùng chung. Xóa bộ nhớ trình duyệt sẽ xóa bản nháp và kho quà; hãy tải JSON để sao lưu. Không giữ mật khẩu trong bản nháp.</p><h3>Những điều nhỏ cần biết</h3><p>Nhạc bắt đầu sau khi người nhận chạm mở quà. Nhạc và hoạt cảnh lặp liên tục; nút tiếp tục / tạm dừng tạm dừng hoặc tiếp tục cả hai. Tôn trọng cài đặt giảm chuyển động của thiết bị. Ảnh mọi tỉ lệ được tự thu gọn vừa khung, giữ tỉ lệ gốc.</p><p>Không có phí theo lượt hay API AI trong ứng dụng. Kho lưu trữ và thiết bị vẫn có giới hạn dung lượng thực tế; không phải lưu trữ vô hạn.</p></div>`,true);}
 async function run(fn){try{await fn();}catch(e){toast(e.message||'Có lỗi. Hãy thử lại.',true);}}
 async function action(name,el){if(busy&&!['close-modal'].includes(name)){toast('Đang gói ghém nội dung. Đợi một chút nhé.');return;}switch(name){case 'nav-editor':renderEditor();break;case 'nav-library':await renderLibrary();break;case 'help':help();break;case 'form-step':step=+el.dataset.step;renderPanel();break;case 'next-form':if(step<4){step++;renderPanel();}else preview();break;case 'new':{if(interacted&&!confirm('Bắt đầu món quà mới? Bản nháp hiện tại sẽ được thay thế; quà đã tạo link vẫn còn.'))break;for(const u of urls.values())URL.revokeObjectURL(u);urls=new Map();config=defaults();assets=new Map();saved=null;localId=null;lock=false;password='';step=1;renderEditor();changed();break;}case 'match-all':{config.steps.forEach(s=>s.transition='match');changed();renderPanel();player?.goTo(player.getState().index);player?.toggle();toast('Đã bật khớp chuyển động kết hợp cho mọi slide.');break;}case 'step-add':if(config.steps.length>=LIMITS.steps)throw Error('Mỗi món quà hỗ trợ tối đa 40 đoạn.');config.steps.push({id:crypto.randomUUID(),line:'Một điều dễ thương nữa dành cho {ten}…',subline:'',seconds:7,scene:'stars',emotion:'happy',photoId:'',transition:'match'});changed();renderPanel();renderSceneStrip();player?.goTo(config.steps.length-1);break;case 'step-remove':if(config.steps.length>1){config.steps.splice(+el.dataset.index,1);changed();renderPanel();renderSceneStrip();}break;case 'step-up':case 'step-down':{const i=+el.dataset.index,j=i+(name==='step-up'?-1:1);if(j>=0&&j<config.steps.length){[config.steps[i],config.steps[j]]=[config.steps[j],config.steps[i]];changed();renderPanel();renderSceneStrip();player?.goTo(j);}break;}case 'scene-preview':player?.goTo(+el.dataset.index);break;case 'device':device=el.dataset.device;$('#previewSpace').classList.toggle('mobile',device==='mobile');$$('[data-action="device"]').forEach(b=>b.classList.toggle('active',b.dataset.device===device));break;case 'robot-edit':robotIndex=player?.getState().index||0;step=3;renderPanel();$('#formPanel').scrollTop=0;$('#robotEmotion')?.focus();break;case 'preview':preview();break;case 'theme':{const t=themes[el.dataset.theme];if(t){config.theme=el.dataset.theme;config.eyeColor=t.eyes;config.accent=t.accent;changed();renderPanel();}break;}case 'upload-photos':$('#photosFile').click();break;case 'upload-sticker':$('#stickerFile').click();break;case 'upload-background':$('#bgFile').click();break;case 'upload-audio':$('#audioFile').click();break;case 'remove-sticker':removeAsset('sticker');break;case 'remove-background':removeAsset('background');break;case 'remove-audio':removeAsset('audio');break;case 'photo-remove':{const i=+el.dataset.index,id=config.photos[i].id;config.photos.splice(i,1);assets.delete(id);config.steps.forEach(s=>{if(s.photoId===id)s.photoId='';});changed();renderPanel();break;}case 'photo-up':case 'photo-down':{const i=+el.dataset.index,j=i+(name==='photo-up'?-1:1);if(j>=0&&j<config.photos.length){[config.photos[i],config.photos[j]]=[config.photos[j],config.photos[i]];changed();renderPanel();}break;}case 'publish':await publish(false);break;case 'publish-copy':await publish(true);break;case 'share-saved':if(saved)await shareModal(saved);break;case 'save-local':busy=true;try{await saveLocal();}finally{busy=false;}break;case 'export-json':await exportFile();break;case 'import':$('#importFile').click();break;case 'close-modal':dismissModal();break;case 'copy-link':{const input=$('#shareUrl');try{await navigator.clipboard.writeText(input.value);toast('Đã sao chép link.');}catch{input.select();toast('Link đã được chọn. Nhấn Ctrl+C để sao chép.');}break;}case 'download-qr':toast('Đang tải ảnh mã QR PNG về máy.');break;case 'edit-legacy':await openLegacy(el.dataset.id);break;case 'share-online':await shareModal({id:el.dataset.id,title:el.closest('article').querySelector('h2').textContent});break;case 'backup-online':await backupOnline(el.dataset.id);break;case 'delete-online':await deleteCloudLink(el.dataset.id,el);break;case 'edit-saved':toast('Đang mở món quà…');await openSaved(el.dataset.id);break;case 'backup-saved':{const item=await draftDB('get',el.dataset.id,'projects');if(!item)throw Error('Món quà không còn trong kho.');download(new Blob([JSON.stringify(item.packet)],{type:'application/json;charset=utf-8'}),safeName(item.title)+'.loithuong.json');toast('Đã tải JSON về máy.');break;}case 'delete-saved':if(confirm('Xóa món quà này khỏi kho trên thiết bị? Link đã tạo vẫn được giữ.')){await draftDB('delete',el.dataset.id,'projects');if(localId===el.dataset.id){localId=null;changed();}await renderLibrary();toast('Đã xóa món quà khỏi kho.');}break;case 'library-refresh':await renderLibrary(true);break;}}
 function click(e){const b=e.target.closest('[data-action]');if(b&&!b.disabled)run(()=>action(b.dataset.action,b));}
 function input(e,force=false){const el=e.target;if(!force&&(el.tagName==='SELECT'||el.type==='checkbox'))return;if(el.dataset.field){const k=el.dataset.field;config[k]=el.type==='checkbox'?el.checked:['volume','speed'].includes(k)?Number(el.value):el.value;if(k==='volume'&&$('#volumeValue'))$('#volumeValue').textContent=Math.round(config.volume*100)+'%';if(el.type==='color'){const b=el.parentElement.querySelector('b');if(b)b.textContent=el.value;}changed();}if(el.dataset.stepField){const s=config.steps[+el.dataset.index],k=el.dataset.stepField;if(s){s[k]=k==='seconds'?Math.max(3,Math.min(25,Number(el.value)||3)):el.value;changed();if(['transition','media','photoId','scene'].includes(k)||k==='emotion'&&['wink-left','wink-right','closed-stars'].includes(s[k])){player?.goTo(+el.dataset.index);player?.toggle();}renderSceneStrip();if(['media','scene','emotion'].includes(k)&&step===1)renderPanel();}}if(el.dataset.photoCaption){const p=config.photos.find(p=>p.id===el.dataset.photoCaption);if(p){p.caption=el.value;changed();}}if(el.id==='giftPassword')password=el.value;}
 function change(e){if(e.target.id==='robotSceneSelect'){robotIndex=Math.max(0,Math.min(config.steps.length-1,Number(e.target.value)||0));renderPanel();player?.goTo(robotIndex);return;}if(e.target.id==='lockGift'){lock=e.target.checked;$('#passwordFields').hidden=!lock;changed();}const kinds={photosFile:'photo',bgFile:'background',stickerFile:'sticker',audioFile:'audio'};if(kinds[e.target.id]){const files=[...e.target.files];e.target.value='';run(()=>addFiles(files,kinds[e.target.id]));}if(e.target.id==='importFile'){const file=e.target.files[0];e.target.value='';run(()=>readImport(file));}if(e.target.tagName==='SELECT'||e.target.type==='checkbox')input(e,true);if(e.target.dataset.stepField==='seconds'){e.target.value=config.steps[+e.target.dataset.index].seconds;renderPanel();}}
 function focus(e){if(e.target.dataset.stepField)player?.goTo(+e.target.dataset.index);}
 function keydown(e){const b=e.target.closest('.st-upload');if(b&&(e.key==='Enter'||e.key===' ')){e.preventDefault();run(()=>action(b.dataset.action,b));}}
 function drag(e){if(e.target.closest('.st-upload')){e.preventDefault();e.target.closest('.st-upload').classList.add('drag');}}
 function drop(e){const z=e.target.closest('.st-upload');if(z){e.preventDefault();z.classList.remove('drag');run(()=>addFiles([...e.dataTransfer.files],'photo'));}}
 function before(e){if(busy||interacted&&draftVersion<version){e.preventDefault();e.returnValue='';}}
 root.addEventListener('click',click);root.addEventListener('input',input);root.addEventListener('change',change);root.addEventListener('focusin',focus);root.addEventListener('keydown',keydown);root.addEventListener('dragover',drag);root.addEventListener('dragleave',e=>e.target.closest('.st-upload')?.classList.remove('drag'));root.addEventListener('drop',drop);window.addEventListener('beforeunload',before);$('#stDialog').addEventListener('cancel',e=>{e.preventDefault();dismissModal();});
 renderEditor();draftDB('get','current').then(d=>{if(!d||interacted||disposed)return;try{config=validateConfig(d.config,true);assets=new Map((d.assets||[]).map(a=>[a.id,{blob:a.blob,name:a.name,mime:a.mime,kind:a.kind}]));saved=d.saved||null;localId=d.localId||null;lock=!!d.lock;password='';draftVersion=version;renderEditor();toast('Đã mở bản nháp lần trước trên thiết bị này.');}catch{toast('Bản nháp cũ không đọc được. Bạn có thể nhập file HTML/JSON đã sao lưu.',true);}}).catch(()=>status('Bản nháp chưa được lưu trên thiết bị'));
 return ()=>{disposed=true;if(publishTask&&!publishTask.committing)publishTask.controller.abort();player?.destroy();modalCleanup?.();clearTimeout(draftTimer);clearTimeout(toastTimer);for(const u of urls.values())URL.revokeObjectURL(u);window.removeEventListener('beforeunload',before);root.removeEventListener('click',click);root.removeEventListener('input',input);root.removeEventListener('change',change);root.removeEventListener('focusin',focus);root.removeEventListener('keydown',keydown);root.removeEventListener('dragover',drag);root.removeEventListener('drop',drop);};
}

